.darma-loader-darma-b17-note-counter { --accent: var(--loader-color, #047857); --accent-2: var(--loader-secondary-color, #a7f3d0); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .66); position: relative; overflow: hidden; }
.darma-loader-darma-b17-note-counter .darma-loader-darma-b17-note-counter__hopper { position: absolute; left: 8%; top: 4%; width: 32%; height: 26%; border-radius: 4px 4px 2px 2px; background: linear-gradient(#64748b, #1e293b); }
.darma-loader-darma-b17-note-counter .darma-loader-darma-b17-note-counter__tray { position: absolute; right: 6%; bottom: 6%; width: 40%; height: 12%; border-radius: 3px; background: linear-gradient(#475569, #0f172a); }
.darma-loader-darma-b17-note-counter span { position: absolute; left: 12%; top: 26%; width: 26%; height: 12%; border-radius: 2px; background: linear-gradient(90deg, var(--accent-2), var(--accent)); box-shadow: inset 0 0 0 1px color-mix(in srgb, #000 22%, transparent); animation: darma-loader-darma-b17-note-counter-count-flick calc(var(--loader-speed, 1s) * 1.5) cubic-bezier(.4, 0, .3, 1) infinite; }
.darma-loader-darma-b17-note-counter span:nth-of-type(1) { animation-delay: calc(var(--loader-speed, 1s) * -1.2); }
.darma-loader-darma-b17-note-counter span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * -.9); }
.darma-loader-darma-b17-note-counter span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-darma-b17-note-counter span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * -.3); }
.darma-loader-darma-b17-note-counter span:nth-of-type(5) { animation-delay: 0s; }
@keyframes darma-loader-darma-b17-note-counter-count-flick { 0% { opacity: 0; transform: translate(0, 0) rotate(-6deg); } 10% { opacity: 1; } 46% { transform: translate(90%, 60%) rotate(14deg); } 82% { opacity: 1; transform: translate(180%, 200%) rotate(0deg); } 100% { opacity: 0; transform: translate(180%, 210%) rotate(0deg); } }

